"""Tests for tools/check_requirements_lock.py."""

from __future__ import annotations

import importlib.util
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent

_spec = importlib.util.spec_from_file_location(
    "check_requirements_lock", REPO_ROOT / "tools" / "check_requirements_lock.py"
)
assert _spec is not None and _spec.loader is not None
lockcheck = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(lockcheck)

LOCK = """\
# This file was autogenerated by uv via the following command:
#    uv pip compile requirements.txt --universal --generate-hashes -o requirements-lock.txt
alpha-pkg==1.2.0 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via -r requirements.txt
beta==2.0.0 ; sys_platform != 'win32' \\
    --hash=sha256:cccc
    # via -r requirements.txt
gamma[extra]==0.5.1 \\
    --hash=sha256:dddd
"""


def _write(tmp_path: Path, requirements: str, lock: str = LOCK) -> tuple[Path, Path]:
    req = tmp_path / "requirements.txt"
    req.write_text(requirements, encoding="utf-8")
    lck = tmp_path / "requirements-lock.txt"
    lck.write_text(lock, encoding="utf-8")
    return req, lck


def test_repository_lock_covers_requirements():
    assert lockcheck.check(REPO_ROOT / "requirements.txt", REPO_ROOT / "requirements-lock.txt") == []


def test_satisfied_requirements_pass(tmp_path):
    req, lck = _write(
        tmp_path,
        "# comment\nAlpha_Pkg>=1.0,<2  # trailing comment\n"
        'beta==2.0.0; sys_platform != "win32"\ngamma[extra]\n--index-url https://example.com/simple\n',
    )
    assert lockcheck.check(req, lck) == []
    assert lockcheck.main([str(req), str(lck)]) == 0


def test_missing_package_is_reported(tmp_path, capsys):
    req, lck = _write(tmp_path, "alpha-pkg==1.2.0\nnew-package==3.0\n")
    problems = lockcheck.check(req, lck)
    assert len(problems) == 1 and "new-package" in problems[0] and "not pinned" in problems[0]
    assert lockcheck.main([str(req), str(lck)]) == 1
    assert "out of date" in capsys.readouterr().out


def test_unsatisfied_version_is_reported(tmp_path):
    req, lck = _write(tmp_path, "alpha-pkg>=1.3\n")
    problems = lockcheck.check(req, lck)
    assert len(problems) == 1 and "1.2.0" in problems[0] and ">=1.3" in problems[0]


def test_included_files_are_followed(tmp_path):
    (tmp_path / "base.txt").write_text("missing-dep\n", encoding="utf-8")
    req, lck = _write(tmp_path, "-r base.txt\nalpha-pkg\n")
    problems = lockcheck.check(req, lck)
    assert len(problems) == 1 and "missing-dep" in problems[0]
